import{_ as e,a,c as l,ac as r}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"篮球规则 · 常见判例与误解至官方资料与阅读范围","description":"以 FIBA 2026 年五人制规则理解篮球计分、比赛流程、违例、犯规与常见判例","frontmatter":{"title":"篮球规则 · 常见判例与误解至官方资料与阅读范围","description":"以 FIBA 2026 年五人制规则理解篮球计分、比赛流程、违例、犯规与常见判例","splitFrom":"life/personal/sports/basketball-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"篮球规则","summary":"以 FIBA 2026 年五人制规则理解篮球计分、比赛流程、违例、犯规与常见判例","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"篮球规则 · 人数、场地与得分至身体接触与犯规处罚","link":"/life/personal/sports/basketball-rules-part-01"},"next":{"text":"乒乓球规则","link":"/life/personal/sports/table-tennis-rules"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"篮球规则 · 人数、场地与得分至身体接触与犯规处罚","link":"/life/personal/sports/basketball-rules-part-01"},"next":{"text":"乒乓球规则","link":"/life/personal/sports/table-tennis-rules"}},"headers":[],"relativePath":"life/personal/sports/basketball-rules-part-02.md","filePath":"life/personal/sports/basketball-rules-part-02.md"}'),s={name:"life/personal/sports/basketball-rules-part-02.md"};function i(n,t,o,d,p,b){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="篮球规则-·-常见判例与误解至官方资料与阅读范围" tabindex="-1">篮球规则 · 常见判例与误解至官方资料与阅读范围 <a class="header-anchor" href="#篮球规则-·-常见判例与误解至官方资料与阅读范围" aria-label="Permalink to &quot;篮球规则 · 常见判例与误解至官方资料与阅读范围&quot;">​</a></h1><p><a href="/life/personal/sports/basketball-rules">返回分篇目录</a></p><p>篮球比赛的目标是在规定时间内获得更多分数。看懂比赛，先区分两件事：<strong>违例通常导致球权转换，犯规还可能涉及罚球、个人累计和纪律处罚</strong>。</p><p>本文采用 FIBA《Official Basketball Rules 2026》v1.1，自 <strong>2026 年 10 月 1 日</strong>起生效；适用标准五人制篮球。NBA、FIBA 三人篮球、青少年和校园赛事另有规则，不能把不同体系混在一起。文中对 2026 年新增犯规类型保留英文名称，中文采用解释性译法。</p><h2 id="常见判例与误解" tabindex="-1">常见判例与误解 <a class="header-anchor" href="#常见判例与误解" aria-label="Permalink to &quot;常见判例与误解 {#常见判例与误解}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>判断要点</th></tr></thead><tbody><tr><td>持球人突破撞上防守者</td><td>看合法防守位置、接触部位及动作；防守者移动不必然犯规，进攻者也不能推开对手</td></tr><tr><td>投篮球在下落、完全高于篮圈水平时被触及</td><td>可能是干涉得分；触板后仍完全高于篮圈时也有保护条件</td></tr><tr><td>球已经碰过篮圈，再被拍走</td><td>FIBA 不宜照搬 NBA 的篮圈上方圆柱体概括，仍须检查是否干扰篮筐、球入篮过程等</td></tr><tr><td>防守者把进攻方的球碰出界</td><td>通常仍由进攻方入界，保留剩余进攻时间，并非自动重置 24 秒</td></tr><tr><td>防守人伸手碰到了球，也碰到手臂</td><td>“先碰球”不自动排除后续非法接触，须看动作是否造成不利影响</td></tr></tbody></table><h2 id="用三个完整回合串起规则" tabindex="-1">用三个完整回合串起规则 <a class="header-anchor" href="#用三个完整回合串起规则" aria-label="Permalink to &quot;用三个完整回合串起规则 {#用三个完整回合串起规则}&quot;">​</a></h2><p>以下是为理解规则设计的假设场景，不替代裁判对接触动作的判断。</p><ol><li><strong>72∶70，进攻钟剩 4 秒。</strong> 甲在三分线外起跳，球在信号前离手，命中后落在线内。得分看起跳位置与离手时机，甲队增加 3 分，成为 75∶70。若起跳踩线，同样投中只变成 74∶70；不是看落地站在哪儿。</li><li><strong>进攻钟剩 9 秒，投篮打铁。</strong> 球碰对方篮圈后，进攻方拿回球，重置为 14 秒；若只碰篮板，不能以“抢到进攻篮板”为由重置。判断顺序是先看碰没碰篮圈，再看谁重新取得控制。</li><li><strong>一节防守队已有 4 次全队犯规。</strong> 接下来拉住一个尚未开始投篮的对手，按普通侵人犯规应罚 2 球；若犯规的是控球队持球人，他用手推开防守者，则通常让对方掷球入界。两者都计犯规，但不能只看累计数就判罚球。</li></ol><h2 id="观赛入门-一次进攻先看谁做什么" tabindex="-1">观赛入门：一次进攻先看谁做什么 <a class="header-anchor" href="#观赛入门-一次进攻先看谁做什么" aria-label="Permalink to &quot;观赛入门：一次进攻先看谁做什么 {#观赛入门-一次进攻先看谁做什么}&quot;">​</a></h2><p>从发界外球开始，可以依次观察“谁带过中线 → 谁拉开空间或作掩护 → 谁得到投篮机会 → 谁争抢篮板”。这比只盯着持球者更容易看出一次配合的目的。</p><table tabindex="0"><thead><tr><th>常见称呼</th><th>主要观察点</th><th>与规则的关系</th></tr></thead><tbody><tr><td>控球后卫</td><td>运球推进、组织传球</td><td>并没有只有后卫才能运球的规定</td></tr><tr><td>得分后卫、前锋</td><td>接球投篮、突破、无球跑动</td><td>无球跑动也可能被拉拽或非法掩护影响</td></tr><tr><td>中锋</td><td>篮下接应、掩护、篮板</td><td>不能凭身高获得限制区长期停留的例外</td></tr><tr><td>挡拆</td><td>队友先作合法掩护，再转向篮下或外线</td><td>掩护人不能跟着防守者移动去撞挡</td></tr><tr><td>篮板</td><td>投篮不中后的争抢</td><td>“拿到篮板”与“计时一定重置”不是一回事</td></tr><tr><td>球权箭头</td><td>记录交替拥有球权的方向</td><td>不是表示目前谁正在进攻</td></tr></tbody></table><p>这些位置名称描述常见分工，并不锁定某个人只能待在某片区域。上场前先确认规则体系、计时办法、暂停与换人程序，再讨论战术。</p><h2 id="自测-把规则用于比赛" tabindex="-1">自测：把规则用于比赛 <a class="header-anchor" href="#自测-把规则用于比赛" aria-label="Permalink to &quot;自测：把规则用于比赛 {#自测-把规则用于比赛}&quot;">​</a></h2><ol><li>球员踩着三分线起跳，命中算几分？</li><li>运球停止后，自己抛球到空中接回，再次运球合法吗？</li><li>投篮碰篮圈，进攻队抢到篮板，通常重置为多少秒？</li><li>第四节本队已有 5 次全队犯规，持球队员推开防守者，应因为犯规满额送对方罚球吗？</li><li>2026 版中，一名队员两次第 2 类技术犯规是否仅凭这个组合就被自动取消比赛资格？</li></ol><p><strong>答案：</strong> 1. 2 分。2. 通常不合法，属于两次运球。3. 14 秒。4. 不会，控球队的普通侵人犯规由对方掷球入界。5. 不会，但这些犯规计入个人累计，仍须检查是否达到 5 次犯规或存在其他取消资格条件。</p><h2 id="官方资料与阅读范围" tabindex="-1">官方资料与阅读范围 <a class="header-anchor" href="#官方资料与阅读范围" aria-label="Permalink to &quot;官方资料与阅读范围 {#官方资料与阅读范围}&quot;">​</a></h2><p>资料核对日期：2026 年 10 月 23 日。本文依据已读取的规则正文及变更文件归纳；复杂接触、录像回放和特殊处罚仍应结合官方解释与赛事规程。</p><ul><li><a href="https://about.fiba.basketball/en/our-sport/official-basketball-rules" target="_blank" rel="noopener noreferrer">FIBA 官方规则入口</a></li><li><a href="https://about.fiba.basketball/en/services/resource-hub/downloads" target="_blank" rel="noopener noreferrer">FIBA 官方下载中心</a></li><li><a href="https://assets.fiba.basketball/image/upload/documents-corporate-fiba-official-rules-2026-v1-1.pdf" target="_blank" rel="noopener noreferrer">Official Basketball Rules 2026 v1.1</a>：场地、计时、违例及第 36—39 条犯规分类。</li><li><a href="https://assets.fiba.basketball/image/upload/documents-corporate-fiba-official-rules-2026-rule-changes-v1-1-en.pdf" target="_blank" rel="noopener noreferrer">Official Basketball Rules 2026 Changes v1.1</a>：投篮动作、技术犯规分类及新犯规类型的变更说明。</li></ul>',19)])])}const f=e(s,[["render",i]]);export{c as __pageData,f as default};
